// Initialize: switch a socket to non-blocking via fcntl
int flags = fcntl(sd, F_GETFL, 0);          // Read current flags
if (flags < 0) { perror("F_GETFL"); exit(1); }
if (fcntl(sd, F_SETFL, flags | O_NONBLOCK) < 0) {
    perror("F_SETFL"); exit(1);
}

// Alternative: ioctl with FIOSNBIO (BSD style)
#include <sys/ioctl.h>
int on = 1;                                 // 1 = non-blocking, 0 = blocking
ioctl(sd, FIOSNBIO, &on);

// Idiom: non-blocking read in a loop, distinguishing 'no data yet' from real errors
char buf[1024];
for (;;) {
    ssize_t n = recv(sd, buf, sizeof buf, 0);
    if (n > 0) {
        process(buf, n);                         // Got data
    } else if (n == 0) {
        // Peer closed connection cleanly
        close(sd); break;
    } else {                                     // n < 0
        if (errno == EWOULDBLOCK || errno == EAGAIN) {
            // No data right now — do something useful, then retry
            do_other_work();
            continue;
        }
        if (errno == EINTR) continue;            // Interrupted, retry
        perror("recv"); close(sd); break;        // Real error
    }
}

