// SIGIO handler: read whatever is available
void on_socket_ready(int signo) {
    // Inside a signal handler, only async-signal-safe calls are allowed.
    // recv() is async-signal-safe; printf() is NOT.
    char buf[512];
    ssize_t n = recv(global_sd, buf, sizeof buf, 0);
    if (n > 0) write(STDOUT_FILENO, buf, n);
}

int main(void) {
    int sd = socket(AF_INET, SOCK_STREAM, 0);
    // ... connect / bind etc.

    // 1) Install the SIGIO handler
    struct sigaction sa = { .sa_handler = on_socket_ready };
    sigaction(SIGIO, &sa, NULL);

    // 2) Tell the kernel WHO owns the socket for SIGIO delivery
    fcntl(sd, F_SETOWN, getpid());

    // 3) Enable async signalling on this descriptor
    int flags = fcntl(sd, F_GETFL, 0);
    fcntl(sd, F_SETFL, flags | O_ASYNC);

    // 4) Main loop is now free to do other work
    while (1) do_simulation_step();
}

