void accept_loop(int listenfd) {
    while (1) {
        int connfd = accept(listenfd, NULL, NULL);
        if (connfd < 0) continue;

        // Heap-allocate the arg so it outlives the stack frame
        int *parg = malloc(sizeof *parg);
        *parg = connfd;

        pthread_t tid;
        if (pthread_create(&tid, NULL, worker, parg) != 0) {
            close(connfd); free(parg); continue;
        }
        pthread_detach(tid);                 // We will never join — reclaim on exit
    }
}

// select_echo_server.c — compile: gcc select_echo_server.c -o sserv
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT      9000
#define BACKLOG    16

int main(void) {
    // 1. Listening socket
    int listenfd = socket(AF_INET, SOCK_STREAM, 0);
    int yes = 1;
    setsockopt(listenfd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof yes);

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_addr.s_addr = htonl(INADDR_ANY),
        .sin_port = htons(PORT),
    };
    if (bind(listenfd, (struct sockaddr*)&addr, sizeof addr) < 0) { perror("bind"); exit(1); }
    if (listen(listenfd, BACKLOG) < 0) { perror("listen"); exit(1); }
    printf("echo server listening on :%d\n", PORT);

    // 2. Master fd_set tracks every socket we care about
    fd_set master, working;
    FD_ZERO(&master);
    FD_SET(listenfd, &master);
    int maxfd = listenfd;

    char buf[1024];
    while (1) {
        working = master;                           // select() will mutate working
        int n = select(maxfd + 1, &working, NULL, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR) continue;           // signal interrupted the wait
            perror("select"); break;
        }

        // 3. New connection?
        if (FD_ISSET(listenfd, &working)) {
            int connfd = accept(listenfd, NULL, NULL);
            if (connfd >= 0) {
                FD_SET(connfd, &master);
                if (connfd > maxfd) maxfd = connfd;
                printf("+ client fd=%d\n", connfd);
            }
        }

        // 4. Data from any existing client?
        for (int fd = 0; fd <= maxfd; fd++) {
            if (fd == listenfd || !FD_ISSET(fd, &working)) continue;
            ssize_t r = read(fd, buf, sizeof buf);
            if (r <= 0) {                           // EOF or error
                printf("- client fd=%d (%s)\n", fd, r == 0 ? "closed" : strerror(errno));
                close(fd);
                FD_CLR(fd, &master);
            } else {
                write(fd, buf, r);                  // echo
            }
        }
    }
    return 0;
}
